from collections import defaultdict

query_to_responses = defaultdict(list)
for i, line in enumerate(lines):
    if line.startswith('user:'):
        query = line[len('user:'):].strip()
        # Find the next assistant line
        for j in range(i+1, min(i+3, len(lines))):
            if lines[j].startswith('assistant:'):
                resp = lines[j][len('assistant:'):].strip()
                query_to_responses[query].append(resp)
                break

# Check for queries that appear multiple times
for query, responses in query_to_responses.items():
    if len(responses) > 1:
        print(f"Query: {query}")
        for r in responses:
            print(f"  Response: {r}")
        print()
        break  # Just show one for now

# Let me look at the lines that aren't user/assistant/empty
other_lines = []
for i, line in enumerate(lines):
    if not line.startswith('user:') and not line.startswith('assistant:') and line.strip():
        other_lines.append((i, line))

print(f"Number of non-standard lines: {len(other_lines)}")
print("\nFirst 20 non-standard lines:")
for idx, (i, line) in enumerate(other_lines[:20]):
    print(f"  line {i}: {line[:100]}")

# Double check: count all occurrences of this query and verify first one
target_query = "Give me a recommendation for a workout routine."
count = 0
first_response = None
for i, line in enumerate(lines):
    if line.startswith('user:') and line[len('user:'):].strip() == target_query:
        count += 1
        if count == 1:
            for j in range(i+1, min(i+3, len(lines))):
                if lines[j].startswith('assistant:'):
                    first_response = lines[j][len('assistant:'):].strip()
                    print(f"Occurrence #{count} at line {i}")
                    print(f"Response: {first_response}")
                    break

print(f"\nTotal occurrences of this query: {count}")
print(f"First response: {first_response}")
